"use strict";(globalThis.webpackChunkopenim_docs=globalThis.webpackChunkopenim_docs||[]).push([[1721],{88560(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>o,metadata:()=>s,toc:()=>h});const s=JSON.parse('{"id":"golang/architectural/5","title":"How OpenIM Ensures Client-Server Data Consistency in 100,000-Member Groups","description":"If an IM system only needs to support ordinary groups, group member synchronization is usually not a hard problem: after a reconnect, pull the missing data, apply a local diff, and move on.","source":"@site/i18n/en/docusaurus-plugin-content-docs-blog/current/golang/architectural/5.md","sourceDirName":"golang/architectural","slug":"/golang/architectural/5","permalink":"/blog/golang/architectural/5","draft":false,"unlisted":false,"editUrl":"https://github.com/OpenIMSDK/docs/tree/main/docs/blog/golang/architectural/5.md","tags":[],"version":"current","lastUpdatedAt":1781517623000,"sidebarPosition":5,"frontMatter":{"title":"How OpenIM Ensures Client-Server Data Consistency in 100,000-Member Groups","hide_title":true,"sidebar_position":5},"sidebar":"tutorialSidebar","previous":{"title":"Mage Cross-platform Build Instructions","permalink":"/blog/golang/architectural/4"},"next":{"title":"Incremental Version Sync","permalink":"/blog/golang/architectural/6"}}');var r=t(86070),i=t(81753);const o={title:"How OpenIM Ensures Client-Server Data Consistency in 100,000-Member Groups",hide_title:!0,sidebar_position:5},a="How OpenIM Ensures Client-Server Data Consistency in 100,000-Member Groups",l={},h=[{value:"01. Do Not Sync Immediately. First Decide Whether This Sync Is Worth It",id:"01-do-not-sync-immediately-first-decide-whether-this-sync-is-worth-it",level:2},{value:"02. Keep Slimming It Down: Replace \u201cthe Whole Group\u201d with \u201cVersion Diffs\u201d",id:"02-keep-slimming-it-down-replace-the-whole-group-with-version-diffs",level:2},{value:"03. Full Is No Longer the Default. It Is the Final Safety Net",id:"03-full-is-no-longer-the-default-it-is-the-final-safety-net",level:2},{value:"04. When There Are Many Users and Many Groups, Batching Is Required",id:"04-when-there-are-many-users-and-many-groups-batching-is-required",level:2},{value:"05. Move Sync Timing Back: Fill Data Only When the User Actually Needs It",id:"05-move-sync-timing-back-fill-data-only-when-the-user-actually-needs-it",level:2},{value:"06. If Notifications Already Carry the Change, Do Not Compare Again",id:"06-if-notifications-already-carry-the-change-do-not-compare-again",level:2},{value:"07. What You Save Is Not Only Traffic, but Also Memory",id:"07-what-you-save-is-not-only-traffic-but-also-memory",level:2},{value:"08. You Do Not Need All Details Locally to Support Search and Display",id:"08-you-do-not-need-all-details-locally-to-support-search-and-display",level:2},{value:"09. The Essence of This Redesign: Split Sync into Five Questions",id:"09-the-essence-of-this-redesign-split-sync-into-five-questions",level:2},{value:"Conclusion",id:"conclusion",level:2}];function c(e){const n={h1:"h1",h2:"h2",header:"header",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"how-openim-ensures-client-server-data-consistency-in-100000-member-groups",children:"How OpenIM Ensures Client-Server Data Consistency in 100,000-Member Groups"})}),"\n",(0,r.jsx)(n.p,{children:"If an IM system only needs to support ordinary groups, group member synchronization is usually not a hard problem: after a reconnect, pull the missing data, apply a local diff, and move on."}),"\n",(0,r.jsx)(n.p,{children:"But once a group grows to tens of thousands or even 100,000 members, everything changes. Group member synchronization is no longer just a client-side feature. It directly affects server pressure, database writes, local storage usage, request spikes, and UI refresh cadence."}),"\n",(0,r.jsxs)(n.p,{children:["OpenIM did not treat this as a small optimization. It made a much deeper redesign: ",(0,r.jsx)(n.strong,{children:"instead of treating \u201csync all members\u201d as the default action, OpenIM split synchronization into five layers: judgment, incrementality, fallback, batching, and lazy loading"}),"."]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{alt:"OpenIM large-group sync evolution",src:t(16692).A+"",width:"1792",height:"1024"})}),"\n",(0,r.jsx)(n.h2,{id:"01-do-not-sync-immediately-first-decide-whether-this-sync-is-worth-it",children:"01. Do Not Sync Immediately. First Decide Whether This Sync Is Worth It"}),"\n",(0,r.jsx)(n.p,{children:"The early approach to large-group synchronization was straightforward: fetch all group members first, compare them with local data, and then update the local store."}),"\n",(0,r.jsx)(n.p,{children:"This works for small groups, but the cost quickly scales up in large-group scenarios: the larger the group, the more data must be moved; the more active the group, the more often synchronization is triggered; and the more users there are, the more easily the server is repeatedly hit by the same class of requests."}),"\n",(0,r.jsxs)(n.p,{children:["So OpenIM\u2019s first step was not to make synchronization run faster, but to teach the system to decide first: ",(0,r.jsx)(n.strong,{children:"is this sync actually necessary?"})]}),"\n",(0,r.jsx)(n.p,{children:"It starts with a lightweight set digest to determine whether the member set has really changed. If the digest matches, there is no need to transfer the full member list again. Only when the digest differs does the system enter the following sync flow. This matters because it turns the sync cost from \u201cmove a large amount of data\u201d into \u201cperform one lightweight comparison first.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"However, a digest can only block requests where nothing has changed. It cannot handle highly active large groups on its own. If members frequently join, leave, get muted, change roles, or update profile information, the digest will fail often. So the digest is not the destination. It is only the first gate."}),"\n",(0,r.jsx)(n.h2,{id:"02-keep-slimming-it-down-replace-the-whole-group-with-version-diffs",children:"02. Keep Slimming It Down: Replace \u201cthe Whole Group\u201d with \u201cVersion Diffs\u201d"}),"\n",(0,r.jsx)(n.p,{children:"The real shift happens in the second step."}),"\n",(0,r.jsx)(n.p,{children:"OpenIM changed group member synchronization from \u201cfull retrieval\u201d to \u201cversion-driven incremental synchronization.\u201d In other words, the system no longer focuses on \u201cwho are all the members in this group?\u201d It focuses on \u201cwhat changed since the last version I synced?\u201d"}),"\n",(0,r.jsx)(n.p,{children:"This redefines the sync target:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"who was removed;"}),"\n",(0,r.jsx)(n.li,{children:"who was added;"}),"\n",(0,r.jsx)(n.li,{children:"whose profile changed;"}),"\n",(0,r.jsx)(n.li,{children:"whose permission or ordering changed;"}),"\n",(0,r.jsx)(n.li,{children:"and when the system must switch directly to fallback mode."}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"At its core, this turns synchronization from \u201crebuild the entire group\u201d into \u201capply a version diff.\u201d The client only needs to remember which version it has already synced to. The next sync only needs to look at changes after that version. The server also no longer returns the entire member set every time; it returns the smallest update set based on version differences."}),"\n",(0,r.jsx)(n.p,{children:"After this step, large-group synchronization truly enters the incremental era."}),"\n",(0,r.jsx)(n.h2,{id:"03-full-is-no-longer-the-default-it-is-the-final-safety-net",children:"03. Full Is No Longer the Default. It Is the Final Safety Net"}),"\n",(0,r.jsx)(n.p,{children:"When many systems implement incremental synchronization, their biggest risk is losing consistency while chasing smaller deltas."}),"\n",(0,r.jsx)(n.p,{children:"OpenIM does not do that. It keeps a full fallback path: if the version chain is discontinuous, the version anchor does not match, or the system determines that the diff is too large, it stops forcing incremental sync and switches back to a complete recovery path."}),"\n",(0,r.jsx)(n.p,{children:"But this \u201ccomplete recovery\u201d is not the old-style full pull. It is closer to a realignment: first restore the current correct state, then reconnect the following incremental chain. In other words, Full does not mean returning to the old path. It lets the system regain a stable footing when something abnormal happens."}),"\n",(0,r.jsxs)(n.p,{children:["This is critical. In large-group synchronization, the worst outcome is not \u201ca bit slower,\u201d but \u201ca bit slower and still incorrect.\u201d OpenIM\u2019s direction is clear: ",(0,r.jsx)(n.strong,{children:"incremental sync is the main road; Full is only the seat belt"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"04-when-there-are-many-users-and-many-groups-batching-is-required",children:"04. When There Are Many Users and Many Groups, Batching Is Required"}),"\n",(0,r.jsx)(n.p,{children:"Another major problem is that \u201cone user can belong to many groups.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"Typical examples include customer service accounts, operations accounts, and bot accounts. After login, they may face a large number of group synchronization requests at the same time. If each group performs its own version comparison independently, the system can be saturated instantly."}),"\n",(0,r.jsx)(n.p,{children:"OpenIM handles this by batching synchronization requests and controlling the threshold of returned results. The number of requests cannot grow without bounds, and the amount of change data returned by the server cannot grow without bounds either. Once accumulated changes reach an upper limit, the system stops there and continues in the next batch."}),"\n",(0,r.jsx)(n.p,{children:"This may look like simple \u201cbatch processing,\u201d but its essence is turning synchronization from an unbounded operation into a bounded window:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"requests do not pile up endlessly;"}),"\n",(0,r.jsx)(n.li,{children:"the server is not dragged into a cascading failure by one user;"}),"\n",(0,r.jsx)(n.li,{children:"and the client does not push too much data into memory at once."}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"This step solves the question of \u201chow do we keep the system from losing control after scale is amplified?\u201d"}),"\n",(0,r.jsx)(n.h2,{id:"05-move-sync-timing-back-fill-data-only-when-the-user-actually-needs-it",children:"05. Move Sync Timing Back: Fill Data Only When the User Actually Needs It"}),"\n",(0,r.jsx)(n.p,{children:"The most wasteful sync is not slow sync. It is syncing something the user never opens."}),"\n",(0,r.jsx)(n.p,{children:"One important later redesign in OpenIM was to move the timing of group synchronization backward. It no longer requires every group\u2019s members to be fully synchronized the moment a user comes online. Instead, synchronization is attached to the conversation lifecycle: first make sure the user can enter the system, then gradually complete the corresponding group information when the user actually enters a related conversation."}),"\n",(0,r.jsx)(n.p,{children:"The benefit is direct:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"the synchronization spike after reconnect is smoothed out;"}),"\n",(0,r.jsx)(n.li,{children:"groups the user does not currently care about no longer compete for the first wave of resources;"}),"\n",(0,r.jsx)(n.li,{children:"group synchronization changes from a single burst into a gradual process along the user\u2019s access path."}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"This is a classic lazy-loading strategy. It does not mean \u201cdo not sync.\u201d It means \u201csync only when synchronization becomes valuable.\u201d"}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{alt:"OpenIM large-group sync architecture",src:t(52806).A+"",width:"1792",height:"1024"})}),"\n",(0,r.jsx)(n.h2,{id:"06-if-notifications-already-carry-the-change-do-not-compare-again",children:"06. If Notifications Already Carry the Change, Do Not Compare Again"}),"\n",(0,r.jsx)(n.p,{children:"Many changes in large groups already arrive at the client through notifications."}),"\n",(0,r.jsx)(n.p,{children:"For example, member joins, member leaves, kicks, role changes, group profile changes, and mute-status changes all provide enough information to tell the client what changed. OpenIM does not waste these notifications. It turns them directly into local synchronization actions and lets the unified sync framework persist the updates."}),"\n",(0,r.jsx)(n.p,{children:"This has two benefits:"}),"\n",(0,r.jsxs)(n.ol,{children:["\n",(0,r.jsx)(n.li,{children:"fewer repeated requests, because the client no longer asks again when it already knows what changed;"}),"\n",(0,r.jsx)(n.li,{children:"unified storage logic, because both active pulls and notification-triggered updates eventually go through the same update chain."}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"To avoid repeated processing in a short period of time, the system also serializes and deduplicates group synchronization actions. This detail may look small, but in high-frequency notification scenarios for large groups, it noticeably reduces jitter."}),"\n",(0,r.jsx)(n.h2,{id:"07-what-you-save-is-not-only-traffic-but-also-memory",children:"07. What You Save Is Not Only Traffic, but Also Memory"}),"\n",(0,r.jsx)(n.p,{children:"When people look at synchronization optimization, they often look at network traffic first. But in large-group scenarios, memory is just as important."}),"\n",(0,r.jsx)(n.p,{children:"The old approach has a problem: to determine whether something changed, the client often needs to load a large number of local member objects first, then compare them with server results. Once the group is large, that process itself becomes heavy."}),"\n",(0,r.jsx)(n.p,{children:"OpenIM reverses the order:"}),"\n",(0,r.jsx)(n.p,{children:"First compare versions and digests, then decide whether there is a delta;\nonly after confirming that something changed does the system load the subset of data that actually needs to be updated."}),"\n",(0,r.jsx)(n.p,{children:"As a result, the system compares \u201cchange identifiers\u201d instead of complete objects. The outcome is less reading, less comparison, less allocation, and fewer triggers. Both the client and the server become lighter."}),"\n",(0,r.jsx)(n.h2,{id:"08-you-do-not-need-all-details-locally-to-support-search-and-display",children:"08. You Do Not Need All Details Locally to Support Search and Display"}),"\n",(0,r.jsx)(n.p,{children:"Large-group synchronization also raises a practical question: if the client does not store every group member\u2019s full details locally, will search become incomplete?"}),"\n",(0,r.jsx)(n.p,{children:"OpenIM does not force a binary choice. It breaks the problem apart:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"if the business values complete local search more, it can synchronize more member information;"}),"\n",(0,r.jsx)(n.li,{children:"if the business values startup speed and lower server pressure more, it can synchronize only the necessary information;"}),"\n",(0,r.jsx)(n.li,{children:"if the business wants both, part of the search capability can be placed on the server side."}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"In other words, OpenIM does not treat \u201ceverything must be stored locally\u201d as the only answer. It leaves room for business trade-offs. Group lists, group details, on-demand fetching, and information completion can be combined to support the large-group experience without overloading local storage."}),"\n",(0,r.jsx)(n.h2,{id:"09-the-essence-of-this-redesign-split-sync-into-five-questions",children:"09. The Essence of This Redesign: Split Sync into Five Questions"}),"\n",(0,r.jsx)(n.p,{children:"OpenIM ultimately does not solve large-group synchronization with one trick. It splits the problem into five questions:"}),"\n",(0,r.jsxs)(n.table,{children:[(0,r.jsx)(n.thead,{children:(0,r.jsxs)(n.tr,{children:[(0,r.jsx)(n.th,{children:"Question"}),(0,r.jsx)(n.th,{children:"Handling Method"})]})}),(0,r.jsxs)(n.tbody,{children:[(0,r.jsxs)(n.tr,{children:[(0,r.jsx)(n.td,{children:"Should we sync?"}),(0,r.jsx)(n.td,{children:"First check whether the digest and version changed."})]}),(0,r.jsxs)(n.tr,{children:[(0,r.jsx)(n.td,{children:"What should we sync?"}),(0,r.jsx)(n.td,{children:"Sync only the diff, not the whole group."})]}),(0,r.jsxs)(n.tr,{children:[(0,r.jsx)(n.td,{children:"How much should we sync?"}),(0,r.jsx)(n.td,{children:"Batch requests, set upper limits, and process data in windows."})]}),(0,r.jsxs)(n.tr,{children:[(0,r.jsx)(n.td,{children:"When should we sync?"}),(0,r.jsx)(n.td,{children:"Follow the conversation lifecycle and lazy-load on demand."})]}),(0,r.jsxs)(n.tr,{children:[(0,r.jsx)(n.td,{children:"What if sync fails?"}),(0,r.jsx)(n.td,{children:"Use Full as the fallback and realign the current state."})]})]})]}),"\n",(0,r.jsx)(n.p,{children:"These five layers together are the core of the redesign."}),"\n",(0,r.jsx)(n.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,r.jsx)(n.p,{children:"The core of OpenIM\u2019s group member synchronization redesign is not \u201csync more, faster,\u201d but \u201csync less, more deliberately.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"It turns full synchronization into digest judgment, digest judgment into version diffs, version diffs into batching and thresholds, unified bursts into lazy loading, and repeated comparisons into notification-driven local updates. The final result is lower server pressure, lighter clients, faster local recovery, and a more stable large-group experience."})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},77462(e,n,t){var s=t(30758),r=Symbol.for("react.element"),i=Symbol.for("react.fragment"),o=Object.prototype.hasOwnProperty,a=s.__SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED.ReactCurrentOwner,l={key:!0,ref:!0,__self:!0,__source:!0};function h(e,n,t){var s,i={},h=null,c=null;for(s in void 0!==t&&(h=""+t),void 0!==n.key&&(h=""+n.key),void 0!==n.ref&&(c=n.ref),n)o.call(n,s)&&!l.hasOwnProperty(s)&&(i[s]=n[s]);if(e&&e.defaultProps)for(s in n=e.defaultProps)void 0===i[s]&&(i[s]=n[s]);return{$$typeof:r,type:e,key:h,ref:c,props:i,_owner:a.current}}n.Fragment=i,n.jsx=h,n.jsxs=h},86070(e,n,t){e.exports=t(77462)},52806(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/openim-group-sync-architecture-64678455f4d3997c918d72ba7d8e9935.png"},16692(e,n,t){t.d(n,{A:()=>s});const s=t.p+"assets/images/openim-group-sync-evolution-cff30a6d612ef5cc721aa563b158788b.png"},81753(e,n,t){t.d(n,{R:()=>o,x:()=>a});var s=t(30758);const r={},i=s.createContext(r);function o(e){const n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);